void conversationTimeoutTest() throws Exception {
    ConversationContext.ContextHandler handler = conversationContext.sendRequest(new Date()).expectResponse(Date.class, Duration.ofMillis(500)).onTimeout(e -> {
        timeout.set(true);
    }).onError((value, throwable) -> {
        error.set(true);
    }).handle((answer) -> {
